'use strict';
let shelfTopic=null,shelfTopicQuery='',shelfFileQuery='',shelfStatus='all',shelfReturn=false,shelfScroll=0;
for(const t of ['Other equipment',...all().map(q=>q.equipment)])if(t&&!equipment.includes(t)){equipment.push(t);topicsByDepartment.General.push(t)}
const renderBeforeShelf=render,navBeforeShelf=nav,navRenderBeforeShelf=renderNav,detailBeforeShelf=detail;
function shelfNormalize(s){return String(s).toLowerCase().replace(/\bfwg\b/g,'fresh water generator')}
function matchingShelfTopics(){const words=shelfNormalize(shelfTopicQuery).split(/\s+/).filter(Boolean);return Object.fromEntries(Object.entries(topicsByDepartment).map(([dept,topics])=>[dept,topics.filter(t=>words.every(w=>shelfNormalize(t+' '+dept).includes(w)))]))}
function shelfQuestions(){if(!shelfTopic||!equipment.includes(shelfTopic))return[];const words=shelfNormalize(shelfFileQuery).split(/\s+/).filter(Boolean);return all().filter(q=>q.equipment===shelfTopic&&words.every(w=>shelfNormalize(q.title+' '+q.body+' '+q.tags.join(' ')+' '+q.answers.map(a=>a.text).join(' ')).includes(w))).filter(q=>shelfStatus==='answered'?q.answers.length>0:shelfStatus==='resolved'?q.status==='Resolved'&&q.outcome:shelfStatus==='saved'?state.saved.includes(q.id):true)}
renderNav=function(){navRenderBeforeShelf();const tabs=[['home','ask','Contribute'],['learn','learn','Library'],['progress','explore','Progress'],['profile','profile','Profile']];for(const id of ['desktopNav','mobileNav'])document.getElementById(id).innerHTML=tabs.map(([p,i,label])=>`<button data-nav="${p}" class="${page===p||p==='progress'&&page==='leaderboard'?'active':''}">${icon(i)}<span>${label}</span></button>`).join('')};
function shelfTopicRows(){const groups=matchingShelfTopics();return Object.entries(groups).filter(([,topics])=>topics.length).map(([dept,topics])=>`<section class="shelf-group"><h2>${dept==='General'?'General shipboard':dept}</h2>${topics.map(t=>{const qs=all().filter(q=>q.equipment===t);const answers=qs.reduce((n,q)=>n+q.answers.length,0);return `<button class="shelf-topic" data-shelf-topic="${esc(t)}"><span class="shelf-book">${icon('learn')}</span><span class="shelf-topic-name"><strong>${esc(t)}</strong><small>${answers} answer${answers===1?'':'s'} filed</small></span><span class="shelf-count" aria-label="${qs.length} question files">${qs.length}</span><span class="chevron">›</span></button>`}).join('')}</section>`).join('')||'<div class="shelf-empty">No matching topic.<p>Try an equipment name, such as Pumps, FWG, or Mooring.</p></div>'}
function shelfRoot(){shelfTopic=null;app.innerHTML=`<header class="shelf-heading"><div class="eyebrow">THE HUB / LIBRARY</div><h1>The crew’s bookshelf.</h1><p>Practical questions and shared experience, filed by topic. Pick a shelf to start reading.</p></header><label class="search">${icon('search')}<input id="shelfTopicSearch" type="search" aria-label="Find a topic" placeholder="Find a topic: FWG, mooring, electrical…" value="${esc(shelfTopicQuery)}"></label><div class="shelf-instruction">Choose a topic first. Question files and their answers appear inside that topic.</div><div class="shelf-columns" id="shelfTopics">${shelfTopicRows()}</div><p class="shelf-footer">Counts include fictional sample cases and your local test entries. No lesson or course publishing is required: each question keeps its discussion together.</p>`;document.querySelector('#shelfTopicSearch').oninput=e=>{shelfTopicQuery=e.target.value;document.querySelector('#shelfTopics').innerHTML=shelfTopicRows()}}
function questionFile(q){const answered=q.answers.length>0;return `<article class="question-file"><button class="file-open" data-shelf-open="${q.id}"><span class="file-symbol">▤</span><span><span class="status ${q.status==='Resolved'?'resolved':''}">${q.status==='Resolved'?'Reported outcome':answered?'Answers inside':'Awaiting an answer'}</span><span class="file-title">${esc(q.title)}</span><span class="file-details"><span>${q.answers.length} answer${q.answers.length===1?'':'s'}</span><span>· ${esc(q.time)}</span>${q.photos.length?`<span>· ${q.photos.length} photo${q.photos.length===1?'':'s'}</span>`:''}</span></span></button><div class="file-bottom"><span>${esc(own(q)?qProfileName():q.author)}${q.id.startsWith('demo')?' · fictional sample':''}</span><button class="save ${state.saved.includes(q.id)?'on':''}" data-save="${q.id}" aria-label="${state.saved.includes(q.id)?'Unsave':'Save'} question file">${icon('save')}${state.saved.includes(q.id)?'Saved':'Save'}</button></div></article>`}
function shelfFiles(){const files=shelfQuestions();return files.length?files.map(questionFile).join(''):'<div class="shelf-empty">No question files match in this topic.<p>Change the filter, or be the first to ask with context.</p><button class="btn quiet" data-shelf-ask="true">Ask in this topic →</button></div>'}
function selectedShelf(){if(!shelfTopic||!equipment.includes(shelfTopic)){shelfRoot();return}const qs=all().filter(q=>q.equipment===shelfTopic);app.innerHTML=`<button class="back shelf-return" data-shelf-root="true">← All topic shelves</button><div class="shelf-path">LIBRARY / ${esc(departmentFor(shelfTopic)||'General')}</div><header class="shelf-heading"><h1>${esc(shelfTopic)}</h1><p>${qs.length} question file${qs.length===1?'':'s'} · ${qs.reduce((n,q)=>n+q.answers.length,0)} answers. Open a file to read the complete discussion.</p></header><label class="search">${icon('search')}<input id="shelfFileSearch" type="search" aria-label="Search within ${esc(shelfTopic)}" placeholder="Search within this topic…" value="${esc(shelfFileQuery)}"></label><div class="shelf-status">${[['all','All files'],['answered','With answers'],['resolved','Reported outcomes'],['saved','Saved']].map(([key,label])=>`<button class="${shelfStatus===key?'active':''}" data-shelf-status="${key}">${label}</button>`).join('')}</div><span class="shelf-search-result-count" id="shelfFileCount">${shelfQuestions().length} files shown</span><div class="shelf-files" id="shelfFiles">${shelfFiles()}</div><p class="shelf-footer">An answer is shared experience. An asker’s reported outcome does not establish that a fix applies to every vessel or model. Follow your procedures, manuals, and responsible officers.</p>`;document.querySelector('#shelfFileSearch').oninput=e=>{shelfFileQuery=e.target.value;document.querySelector('#shelfFiles').innerHTML=shelfFiles();document.querySelector('#shelfFileCount').textContent=shelfQuestions().length+' files shown'}}
detail=function(){detailBeforeShelf();if(shelfReturn){const back=app.querySelector('.back');if(back){back.removeAttribute('data-nav');back.setAttribute('data-shelf-return','true');back.textContent='← '+shelfTopic+' files'}}};
nav=function(p){if(p==='learn'&&state.hubOnboardingCompleted){page='learn';selected=null;shelfTopic=null;shelfTopicQuery='';shelfFileQuery='';shelfStatus='all';shelfReturn=false;render();window.scrollTo(0,0);return}navBeforeShelf(p)};
openSharedSearch=function(text=''){if(!state.hubOnboardingCompleted){nav('welcome');return}page='learn';shelfTopic=null;shelfTopicQuery=String(text||'').trim();shelfFileQuery='';shelfStatus='all';shelfReturn=false;render();window.scrollTo(0,0)};
render=function(){if(page==='learn'&&state.hubOnboardingCompleted){applyTheme();document.body.classList.remove('intro-mode');app.classList.remove('setup-view');renderNav();document.querySelector('#sectionName').textContent='The Hub / Library';if(shelfTopic)selectedShelf();else shelfRoot();return}renderBeforeShelf()};
// Capture source context before older handlers open the shared discussion screen.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open)shelfReturn=false;if(b.dataset.qaTopic){shelfTopic=b.dataset.qaTopic;shelfFileQuery='';shelfStatus='all';shelfReturn=false}if(b.dataset.qaDept){shelfTopic=null;shelfTopicQuery=b.dataset.qaDept;shelfReturn=false}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.shelfTopic){shelfTopic=b.dataset.shelfTopic;shelfFileQuery='';shelfStatus='all';shelfReturn=false;page='learn';render();window.scrollTo(0,0)}if(b.dataset.shelfRoot){shelfTopic=null;shelfTopicQuery='';shelfReturn=false;page='learn';render();window.scrollTo(0,0)}if(b.dataset.shelfStatus){shelfStatus=b.dataset.shelfStatus;render()}if(b.dataset.shelfOpen){shelfScroll=window.scrollY||0;selected=b.dataset.shelfOpen;shelfReturn=true;page='detail';render();window.scrollTo(0,0)}if(b.dataset.shelfReturn){page='learn';selected=null;render();window.scrollTo(0,shelfScroll)}if(b.dataset.shelfAsk){try{const old=JSON.parse(sessionStorage.getItem('crew-draft')||'{}');sessionStorage.setItem('crew-draft',JSON.stringify({...old,equipment:shelfTopic,dept:departmentFor(shelfTopic)||'General'}))}catch{}nav('ask')}});
render();
